import { Controller, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr01206Controller {
  @Delete('/hr-card-items/:hrCardItemId')
  async deleteHrCardItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const idText = req.params['hrCardItemId'];
    if (typeof idText !== 'string' || !/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인사기록카드 항목 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT hr_card_item_id AS "hrCardItemId" FROM hr_card_item WHERE hr_card_item_id = CAST(:id AS bigint)',
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'HR_CARD_ITEM_NOT_FOUND', '대상 인사기록카드 항목을 찾을 수 없습니다.');
      }
      await db.execute(
        'DELETE FROM hr_card_item WHERE hr_card_item_id = CAST(:id AS bigint)',
        { id: idText },
      );
      return {};
    });
  }
}

