import { useState } from 'react';
import {
  call,
  useData,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const ITEM_TYPES: [string, string][] = [
  ['가족', '가족'],
  ['학력', '학력'],
  ['경력', '경력'],
  ['자격·면허', '자격·면허'],
  ['외국어', '외국어'],
  ['인사고과', '인사고과'],
  ['상벌', '상벌'],
  ['출장', '출장'],
  ['부양가족', '부양가족'],
  ['병역', '병역'],
  ['보훈', '보훈'],
];

type Mode =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row }
  | null;

function ItemForm({
  role,
  row,
  employeeId,
  onDone,
}: {
  role: string;
  row?: Row;
  employeeId: unknown;
  onDone: (text: string) => void;
}) {
  const [empId, setEmpId] = useState<unknown>(row ? row.employeeId : employeeId);
  const [itemType, setItemType] = useState<string>(row ? String(row.itemType) : '');
  const [title, setTitle] = useState<string>(row ? String(row.title ?? '') : '');
  const [detail, setDetail] = useState<string>(row ? String(row.detail ?? '') : '');
  const [startDate, setStartDate] = useState<string>(row ? String(row.startDate ?? '') : '');
  const [endDate, setEndDate] = useState<string>(row ? String(row.endDate ?? '') : '');
  const [personName, setPersonName] = useState<string>(row ? String(row.relatedPersonName ?? '') : '');
  const [personRrn, setPersonRrn] = useState<string>('');

  const submit = async () => {
    if (!row && (empId === '' || empId === undefined || empId === null)) {
      throw new Error('임직원을 선택하세요.');
    }
    if (!row && !itemType) {
      throw new Error('항목 유형을 선택하세요.');
    }
    if (!title.trim()) {
      throw new Error('항목명을 입력하세요.');
    }
    if (startDate && endDate && startDate > endDate) {
      throw new Error('시작일이 종료일보다 늦을 수 없습니다.');
    }
    const body: Row = {
      title,
      detail,
      startDate: startDate || undefined,
      endDate: endDate || undefined,
      relatedPersonName: personName || undefined,
    };
    if (personRrn) {
      body.relatedPersonRrn = personRrn;
    }
    if (row) {
      await call('PATCH', '/hr-card-items/' + String(row.hrCardItemId), role, body);
      onDone('인사기록카드 항목을 수정했습니다.');
    } else {
      body.employeeId = empId;
      body.itemType = itemType;
      await call('POST', '/hr-card-items', role, body);
      onDone('인사기록카드 항목을 등록했습니다.');
    }
  };

  return (
    <Form onSubmit={submit} submit={row ? '수정' : '등록'}>
      {!row && (
        <Field label="임직원 ID" required>
          <LookupSelect table="employee" role={role} value={empId} onChange={setEmpId} />
        </Field>
      )}
      {!row && (
        <Field label="항목 유형" required>
          <Select value={itemType} onChange={setItemType} options={ITEM_TYPES} />
        </Field>
      )}
      <Field label="항목명" required>
        <TextInput value={title} onChange={setTitle} />
      </Field>
      <Field label="상세 내용" wide>
        <TextInput value={detail} onChange={setDetail} multiline />
      </Field>
      <Field label="시작일">
        <DateInput value={startDate} onChange={setStartDate} />
      </Field>
      <Field label="종료일">
        <DateInput value={endDate} onChange={setEndDate} />
      </Field>
      <Field label="관련자명">
        <TextInput value={personName} onChange={setPersonName} />
      </Field>
      <Field label="관련자 주민등록번호" hint="암호화하여 저장합니다. 비워 두면 바꾸지 않습니다.">
        <TextInput value={personRrn} onChange={setPersonRrn} />
      </Field>
    </Form>
  );
}

export default function FnSfr01206Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<unknown>('');
  const [itemType, setItemType] = useState<string>('');
  const [applied, setApplied] = useState<{ employeeId: unknown; itemType: string }>({
    employeeId: '',
    itemType: '',
  });
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const size = 20;

  const { data, error, loading, reload } = useData<Page>(async () => {
    if (applied.employeeId === '' || applied.employeeId === undefined) {
      return { items: [], page: 0, size, total: 0 };
    }
    return call<Page>('GET', '/hr-card-items', role, undefined, {
      employeeId: applied.employeeId,
      itemType: applied.itemType,
      page,
      size,
    });
  }, [applied, page, role]);

  const done = (text: string) => {
    setMode(null);
    notify(text);
    reload();
  };

  const remove = async (row: Row) => {
    await call('DELETE', '/hr-card-items/' + String(row.hrCardItemId), role);
    done('인사기록카드 항목을 삭제했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>이력 항목</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ employeeId, itemType });
          }}
          onReset={() => {
            setEmployeeId('');
            setItemType('');
            setPage(0);
            setApplied({ employeeId: '', itemType: '' });
          }}
        >
          <Field label="임직원 ID" required>
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="항목 유형">
            <Select value={itemType} onChange={setItemType} options={ITEM_TYPES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setMode({ kind: 'create' })}>
            항목 등록
          </button>
        </Band>
        {error && <div>{error}</div>}
        <DataTable
          rows={data ? data.items : []}
          empty={loading ? '불러오는 중입니다.' : '임직원을 선택해 조회하세요.'}
          columns={[
            { key: 'hrCardItemId', label: '인사기록카드 항목 ID' },
            {
              key: 'employeeId',
              label: '임직원 ID',
              render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
            },
            { key: 'itemType', label: '항목 유형' },
            { key: 'title', label: '항목명' },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'relatedPersonName', label: '관련자명' },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      setMode({ kind: 'edit', row: r });
                    }}
                  >
                    수정
                  </button>
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      setMode({ kind: 'delete', row: r });
                    }}
                  >
                    삭제
                  </button>
                </span>
              ),
            },
          ]}
        />
        <Pager page={page} size={size} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {mode && mode.kind === 'create' && (
        <Drawer title="인사기록카드 항목 등록" onClose={() => setMode(null)}>
          <ItemForm role={role} employeeId={applied.employeeId} onDone={done} />
        </Drawer>
      )}
      {mode && mode.kind === 'edit' && (
        <Drawer title="인사기록카드 항목 수정" onClose={() => setMode(null)}>
          <ItemForm role={role} row={mode.row} employeeId={mode.row.employeeId} onDone={done} />
        </Drawer>
      )}
      {mode && mode.kind === 'delete' && (
        <Drawer title="인사기록카드 항목 삭제" onClose={() => setMode(null)}>
          <Pairs
            items={[
              ['항목 유형', String(mode.row.itemType ?? '')],
              ['항목명', String(mode.row.title ?? '')],
              ['시작일', <DateText value={mode.row.startDate} />],
              ['종료일', <DateText value={mode.row.endDate} />],
            ]}
          />
          <Form
            danger
            submit="삭제"
            note="삭제한 항목은 되돌릴 수 없습니다."
            onSubmit={() => remove((mode as { kind: 'delete'; row: Row }).row)}
          />
        </Drawer>
      )}
    </div>
  );
}
